      "id": "l-79711839",
      "title": "Fast-Tech und das Problem mit dem Müll",
      "date": "2026-10-20",
      "transcript": "Fast-Tech und das Problem mit dem Müll\n\nSie kosten wenig, gehen schnell kaputt und landen dann im Müll: Fast-Tech-Geräte. Dabei enthalten sie wertvolle Rohstoffe. Trotzdem wird weltweit nur ein kleiner Teil des Elektroschrotts recycelt.\n\nOb Mini-Ventilatoren, billige Ladegeräte oder E-Zigaretten: Fast-Tech-Geräte werden immer beliebter. Ihre schlechte Qualität und ihre kurze Lebensdauer scheinen viele Käuferinnen und Käufer nicht zu stören, weil man die Geräte leicht ersetzen kann. Sie liegen dann kaputt oder sogar unbenutzt im Schrank – oder sie werden im normalen Hausmüll entsorgt, anstatt sie zu recyceln.\n\nWeltweit entstehen jedes Jahr etwa 62 Millionen Tonnen Elektroschrott. Nur 17 Prozent werden recycelt. Der Schaden für die Umwelt ist groß, denn der Müll ist giftig. Falsche Entsorgung verursacht aber noch ein weiteres Problem: Jedes Jahr gehen Millionen Tonnen kritischer Rohstoffe wie Mangan, Gold oder Kupfer verloren – Materialien, die wertvoll sind und im Zentrum geopolitischer Spannungen stehen, wie Magdalena Charytanowicz vom WEEE Forum erklärt.\n\nSelbst die kleinsten Geräte, die eine Platine oder einen Akku haben, sollten recycelt werden, sagt sie. Aber dafür muss sich etwas im Bewusstsein der Menschen ändern. „Wirklich wichtig ist, dass der Vorgang in die täglichen Abläufe integriert werden kann“, sagt Charytanowicz. Bei Projekten in Belgien, Spanien und Slowenien konnten Elektrogeräte kostenlos per Post zurückgeschickt oder an öffentlichen Sammelstellen abgegeben werden. Über 60 Prozent der Menschen nutzten diese Angebote.\n\nRecycling ist wichtig, damit wertvolle Rohstoffe nicht verloren gehen. Allerdings wird auch dafür viel Energie benötigt. Der beste Weg, die Umweltbelastung zu reduzieren, ist laut WEEE Forum eine längere Lebensdauer der Geräte. Dieses Ziel lässt sich zum Beispiel durch ein besseres Design erreichen – oder durch mehr Möglichkeiten zur Reparatur.",
