      "id": "l-79669480",
      "title": "Schülerinnen gegen Sexualisierung der Schuluniform",
      "date": "2026-10-16",
      "transcript": "Schülerinnen gegen Sexualisierung der Schuluniform\n\nSchuluniformen gehören für viele Schülerinnen zum ganz normalen Schulalltag. Doch diese Art der Kleidung wird durch Pornos sexualisiert. Schülerinnen aus Großbritannien wollen das jetzt mit einer Petition ändern.\n\nIn Großbritannien und vielen anderen Ländern gehören Schuluniformen zum Alltag von Schülerinnen und Schülern. Die Einheitlichkeit soll gesellschaftliche Unterschiede verdecken und für ein gutes Gemeinschaftsgefühl sorgen. Aber besonders für Mädchen kann diese Art der Kleidung einen unangenehmen Nebeneffekt haben: Denn solche Uniformen werden auch in Pornos benutzt und in Sexshops verkauft.\n\nBei einer Umfrage der Organisation Plan International von 2018 gab jede dritte der rund 1000 Befragten im Alter von 14 bis 21 Jahren an, schon einmal sexuelle Belästigung beim Tragen einer Schuluniform erlebt zu haben. Dabei werden Mädchen nicht nur angestarrt. Sie werden gefilmt oder erleben das sogenannte „Upskirting“, bei dem unter den Rock fotografiert wird. Manche Menschen schlagen deshalb vor, dass man die Röcke der Uniformen einfach verlängern sollte.\n\nFür die britischen Schülerinnen Aylin und Mae kann das aber nicht die Lösung sein. „Wir sollten nicht den Opfern die Schuld geben“, lautet die Antwort von Aylin. Auch die beiden 15-Jährigen kennen diese Art von unerwünschter Aufmerksamkeit und wollen etwas gegen die Sexualisierung der Schuluniform tun. „Unsere Wahrnehmung dessen, was eine Schuluniform ausmacht, wurde durch diese widerwärtigen Medien verzerrt“, klagt Mae. „Etwas, das eine Gemeinschaft symbolisieren soll, ist in der Gesellschaft mittlerweile in Verruf geraten.“\n\nDeswegen setzen sich die beiden zusammen mit anderen Mitschülerinnen für ein gesetzliches Verbot ein: „Wir wollen Schuluniformen komplett aus der Pornografie verbannen“, sagt Aylin. Dafür haben die Mädchen eine Petition gestartet: Mehr als 27.000 Menschen haben bereits unterschrieben, die Zeitung „The Times“ berichtete. Nun hoffen sie, dass auch ihr Parlament bald über das Thema spricht. Viel Arbeit für etwas, das selbstverständlich sein sollte: „Wir wollen einfach nur verhindern, dass irgendjemand auf diese Art und Weise über Kinder und Schuluniformen denkt“, erklärt Mae.",
