      "id": "l-79650792",
      "title": "Autorin: KI",
      "date": "2026-10-13",
      "transcript": "Autorin: KI\n\nViele Bücher werden heute mit Hilfe von Künstlicher Intelligenz geschrieben. Doch kann man ein menschliches noch von einem maschinellen Werk unterscheiden? Und soll man die Nutzung von KI ablehnen oder akzeptieren?\n\nDer Prix Goncourt ist der wichtigste Literaturpreis Frankreichs. Wer für ihn nominiert wird, hat als Autor oder Autorin einiges erreicht. Thélyson Orélien ist 2026 genau das mit seinem Debütroman „C’était ça ou mourir“ gelungen. Doch dann wurden gegen den kanadisch-haitianischen Autor plötzlich Betrugsvorwürfe erhoben. Nicht er selbst, sondern eine KI soll das Buch geschrieben haben.\n\nAls Reaktion hat man Orélien sehr schnell von der Liste der Nominierten für den Prix Goncourt gestrichen. Die Vorwürfe gegen den Autor sind jedoch zweifelhaft. Denn sie stammen nicht von einem Menschen, sondern ebenfalls von einer KI. Die hat Oréliens Roman geprüft und hält ihn für KI-generiert. Nur: Kann eine Maschine überhaupt beurteilen, ob ein Text von einer Maschine stammt oder nicht? Und selbst wenn: Wie schlimm wäre das?\n\n„Wir werden mit dem Zweifel leben müssen“, sagt Hannes Bajohr. Der Germanistikprofessor untersucht schon seit Jahren, wie KI unseren Blick auf das Schreiben verändert. Bajohr meint: In Zukunft wird es nicht mehr auf die Herkunft, sondern nur noch auf die Qualität eines Textes ankommen. Denn wer ihn geschrieben hat, Mensch oder Maschine, lässt sich nicht mehr eindeutig sagen.\n\nManche Autorinnen und Autoren geben schon offen zu, dass sie mit KI arbeiten. Die Südafrikanerin Coral Hart hat die KI innerhalb eines Jahres über 200 Romane generieren lassen. So viele Bücher schreiben andere Autoren in ihrer ganzen Karriere nicht. Auch US-Autor Luke Stoffel hat für sein preisgekröntes Buch „How To Win One Million Dollars and Shit Glitter“ Hilfe von der KI bekommen. Stoffel ist Legastheniker: Mit den neuen Hilfsmitteln hat er endlich den Mut gefunden, seine Texte zu veröffentlichen. Er findet die Debatte unehrlich – und ist sicher: „Gerade im Moment wird ein Millionen-Bestseller gedruckt, der mit Hilfe von KI entstanden ist.“",
