      "id": "l-79563608",
      "title": "Ein Leben mit Zwängen",
      "date": "2026-10-06",
      "transcript": "Ein Leben mit Zwängen\n\nIst der Herd wirklich aus? Bin ich sauber oder muss ich noch mal duschen? Der Alltag mit einer Zwangserkrankung ist schwierig, die Betroffenen leiden unter starken Ängsten. Doch was kann man dagegen tun?\n\nAls Alex 13 Jahre alt war, musste sie immer genau sieben Dinge am Körper tragen und hatte genau 400 Kontakte in ihrem Handy. Das war der Anfang ihrer Zwangserkrankung. Später bekam sie Angst vor Toiletten und duschte sich nach jedem Toilettenbesuch. Einkaufen, der Haushalt und die Arbeit: Alles wurde zur Herausforderung. „Du guckst dir zu, wie du irre wirst“, sagt die heute 36-Jährige. Alex ist eine von mehr als zwei Millionen Deutschen, die an einer Zwangserkrankung leiden.\n\nOft beginnt die Erkrankung mit einfachen Gedanken, die viele kennen: Ich habe den Herd nicht ausgemacht. Bei Menschen mit einer Zwangserkrankung wird dieser Gedanke aber immer bedrohlicher: Was, wenn deshalb das Haus brennt und Menschen sterben?  Durch wiederholtes Kontrollieren kann die Angst zwar weniger werden, weiß die Psychotherapeutin Katharina Bey – aber der Gedanke an den Herd ist immer noch sehr präsent und bedrohlich.\n\nEine neue Studie hat 36 Genvarianten gefunden, die das Risiko für eine Zwangsstörung erhöhen können. „Etwa 50 Prozent machen die Gene aus, 50 Prozent Umweltfaktoren“, sagt Bey. Eine Rolle könnten zum Beispiel Situationen spielen, in denen Kinder die Kontrolle verlieren, etwa bei der Trennung der Eltern.\n\nDie Studienergebnisse können helfen, die Scham zu verringern, so Bey. Betroffenen wie Jessica Teitz ist es aber egal, warum sie Zwänge haben. Die junge Frau will wissen, was sie dagegen tun kann.\n\nAuch ihre Zwänge begannen im Kindesalter, wurden jahrelang nicht behandelt und immer schlimmer. Erst mit Medikamenten konnte sie wieder das Haus verlassen und eine Verhaltenstherapie beginnen. Dabei stellte sie sich genau den Situationen, die ihre Zwangshandlungen auslösten. „Paradoxerweise werden die Gedanken und Gefühle erst dadurch weniger, dass sie Raum bekommen“, erklärt Bey. Jessica und Alex haben mittlerweile gelernt, mit ihren Zwängen umzugehen, und raten Betroffenen, sich früh Hilfe zu holen. „Je länger du das hast, desto schwerer kommst du wieder raus, und desto länger dauert die Therapie“, sagt Jessica.",
