      "title": "Afrikas wahre Größe",
      "date": "2026-10-02",
      "transcript": "Afrikas wahre Größe\n\nDas Wissen über Afrika ist oft noch von der Kolonialzeit beeinflusst. Doch immer mehr Menschen weisen auf dieses Problem hin. Auf Weltkarten soll der Kontinent nun dank einer Kampagne endlich richtig dargestellt werden.\n\nAuf den Weltkarten, die in Europa üblich sind, sieht der afrikanische Kontinent oft nicht größer als Grönland aus. Dabei ist Afrika rund 14-mal größer als die dänische Insel. Doch die verzerrte Darstellung auf den Karten lässt die Länder in Äquatornähe relativ klein aussehen. Das ist nicht nur ein geographisches Problem: Denn die Verzerrung auf der Karte kann Afrika auch politisch kleiner und schwächer wirken lassen, als es ist.\n\n„Der Platz, der Afrika bis heute zugestanden wird, ist ungerecht“, sagt Togos Außenminister Robert Dussey. „Er entspricht nicht der Realität – weder historisch noch geographisch oder wirtschaftlich.“ Im Namen der Afrikanischen Union hat Dussey deswegen die Kampagne „Correct the Map“ bei den Vereinten Nationen vorgestellt. Mit Erfolg: 164 Staaten der Welt haben im September 2026 dafür gestimmt, dass Weltkarten in Zukunft möglichst flächentreu sein sollen. Statt der alten Mercator-Karten sollen Darstellungen wie die sogenannte „Equal-Earth-Map“ verwendet werden. Die USA waren als einziges Land gegen den Vorschlag.\n\nDie Abstimmung über die Darstellung der Welt ist Teil einer größeren, weltweiten Entwicklung im Bereich von Wissenschaft, Kultur und Gesellschaft, wie der französische Historiker Romain Tiquet erklärt: In zahlreichen Diskussionen über die „Dekolonialisierung des Wissens“ stellen die Menschen seit Ende der 2000er-Jahre immer öfter Fragen wie: „Wer hat die Kategorien festgelegt, in denen wir die Welt denken? [...] Und welche Machtverhältnisse ergeben sich daraus?“\n\nIn einem Land wie Tansania, das erst deutsche und dann britische Kolonie war, bedeutet das etwa, dass die Lehrpläne an den Schulen geändert werden. Im Unterricht behandelt man nun neben globaler Geschichte auch intensiver die Geschichte Tansanias – auf Swahili. „Afrikanische Geschichte aus afrikanischen Perspektiven“ zu beschreiben: das ist für den tansanischen Historiker Philemon Mtoi nicht nur Teil der Dekolonialisierung, sondern „auch ein wichtiger Schritt zu intellektueller Unabhängigkeit und kulturellem Selbstvertrauen.“",
