      "id": "l-79474016",
      "title": "Bezahlbarer Wohnraum für alle – aber wie?",
      "date": "2026-09-29",
      "transcript": "Bezahlbarer Wohnraum für alle – aber wie?\n\nIn vielen europäischen Städten fehlt es an Wohnraum. Entweder man findet gar nichts, oder die verfügbaren Wohnungen sind viel zu teuer. Doch einige Städte arbeiten an Lösungen für das Problem.\n\nWer in Berlin eine Mietwohnung sucht, braucht viel Geduld: Es gibt kaum Angebote, und die wenigen Wohnungen werden oft sehr teuer vermietet. 2021 haben die Berlinerinnen und Berliner ihren Ärger darüber​​​​​​​ in einem Volksentscheid zum Ausdruck gebracht. Er sollte große Wohnungskonzerne dazu zwingen, ihre Wohnungen günstig an die Stadt zu verkaufen. Bisher ist aber nichts passiert. Auch deshalb war das Thema Wohnen bei der Wahl zum Berliner Abgeordnetenhaus 2026 für viele entscheidend. Dass man aber wirklich etwas gegen Mietwucher tun kann, zeigen andere Städte in Europa.\n\nWien etwa hat weniger Probleme mit Wohnungskonzernen als Berlin, denn den Unternehmen gehört dort viel weniger Wohnraum: Schon seit über 100 Jahren vermietet die Stadt viele Wohnungen selbst – heute etwa 220.000. Weitere 200.000 Wohnungen sind öffentlich gefördert. Über die Hälfte der Wienerinnen und Wiener lebt in solchen Wohnungen. Dadurch bleibt auch Wohnraum auf dem freien Markt relativ günstig.\n\nIn der tschechischen Hauptstadt Prag reagiert die Politik darauf, dass viele Menschen zwar Jobs haben, sich aber trotzdem keine Wohnung leisten können. Hier sind einige Wohnungen bestimmten wichtigen Berufsgruppen vorbehalten – zum Beispiel Polizistinnen, Müllwerkern oder Pflegekräften. Sie bezahlen dort etwa 20 Prozent weniger Miete, als üblich wäre. Noch sind es erst etwa 600 Wohnungen, ein Ausbau ist aber geplant.\n\nAuch im irischen Dublin übersteigt die Nachfrage das Wohnungsangebot bei Weitem, und die Mietpreise sind stark gestiegen. Sozialwohnungen gibt es zwar, aber viel zu wenige. Die Stadt hat deshalb ein Wohnungsprogramm beschlossen – für Menschen, die zu wenig für den freien Markt, aber zu viel für eine Sozialwohnung verdienen. Die Wohnungen sind in gemeinnütziger Hand, und die Miete ist rund 30 Prozent niedriger als üblich. Wie wichtig das Angebot ist, zeigen die Zahlen: Auf 104 dieser günstigen Wohnungen kamen über 4000 Bewerbungen.",
