      "id": "l-79373291",
      "title": "Merz gerät nach Landtagswahlen unter Druck",
      "date": "2026-09-22",
      "transcript": "Merz gerät nach Landtagswahlen unter Druck\n\nNach der Landtagswahl in Sachsen-Anhalt verliert die konservative CDU nun auch in Mecklenburg-Vorpommern und Berlin. Gewinner sind die rechte AfD und Die Linke. Für Bundeskanzler Friedrich Merz wird die Lage schwieriger.\n\nEs war ein schlechter Tag für die CDU: Am 6. September 2026 verlor sie bei der Landtagswahl in Sachsen-Anhalt fast 20 Prozent. Die dort als rechtsextremistisch geltende AfD konnte ihr Ergebnis mehr als verdoppeln und mit 43,8 Prozent die Wahl deutlich gewinnen. Nun hat die CDU auch bei den Wahlen in Berlin und Mecklenburg‑Vorpommern stark verloren. In Mecklenburg‑Vorpommern erhielt die Partei sogar weniger als fünf Prozent der Stimmen – und kommt damit zum ersten Mal in ihrer Geschichte nicht in einen deutschen Landtag. Bundeskanzler Friedrich Merz (CDU) nannte das Ergebnis „ein Desaster“.\n\nDie AfD hat im Gegensatz dazu in allen drei Bundesländern stark zugelegt. In Mecklenburg‑Vorpommern hat sie ihr Ergebnis mit 38,2 Prozent der Stimmen mehr als verdoppelt, in Berlin kam sie auf über 16 Prozent. Hier wurde Die Linke mit 25,7 Prozent stärkste Partei – ihre Spitzenkandidatin Elif Eralp könnte die erste Regierende Bürgermeisterin der Linken in Berlin werden. Die SPD hat in Berlin ein Drittel der Stimmen verloren. In Mecklenburg‑Vorpommern blieb sie mit 35,5 Prozent knapp hinter der AfD und wurde zweitstärkste Partei, während sie in Sachsen-Anhalt insgesamt 9,3 Prozent der Stimmen bekam.\n\nDie Wahlergebnisse passen zu der großen Unzufriedenheit der Bevölkerung mit der Regierung von Friedrich Merz, in der die CDU/CSU mit der SPD zusammenarbeitet: Umfragen zeigen, dass die Mehrheit der Deutschen mit dieser Regierung nicht mehr zufrieden ist. Viele Menschen reagieren zum Beispiel kritisch auf die geplanten Reformen der Regierung bei der Kranken- oder Rentenversicherung, deren Kosten stark gestiegen sind. Für die Bürgerinnen und Bürger könnte durch die Änderungen in Zukunft vieles teurer werden.\n\nDurch die Wahlergebnisse gerät die Bundesregierung auch außenpolitisch mehr unter Druck. Die stark gewachsene AfD ist zum Beispiel gegen eine militärische Unterstützung der Ukraine. Merz weiß, dass die Lage schwierig ist. Er will jedoch als Bundeskanzler weitermachen und sagt: „Was jetzt zu tun ist, erfordert Rückgrat, Standhaftigkeit und Geduld. Ich werde das aufbringen. Als Parteivorsitzender der CDU und vor allem als Bundeskanzler unseres Landes.“",
