      "id": "l-79213126",
      "title": "Warum eine Kindheit auf dem Bauernhof gesund ist",
      "date": "2026-09-11",
      "transcript": "Warum eine Kindheit auf dem Bauernhof gesund ist\n\nIn der Forschung untersucht man seit Jahren Kinder, die auf dem Land groß werden. Dabei hat man festgestellt: Sie haben bestimmte Krankheiten seltener als Stadtkinder. Dabei spielen Mikroorganismen eine wichtige Rolle.\n\nZwischen Feldern, Wiesen und Kühen groß zu werden – das stellen sich viele sehr schön vor. Darüber hinaus ist eine Kindheit auf dem Bauernhof aber auch gut für die Gesundheit. Seit 1989 gibt es in der Forschung die „Hygiene-Hypothese“: Kinder, die zu wenig mit Keimen in Kontakt kommen, entwickeln später häufiger Heuschnupfen, Asthma oder Neurodermitis – anders als Kinder, die zum Beispiel durch einen Kuhstall vielen Bakterien ausgesetzt sind.\n\nFrüher dachte man: Je mehr Kontakt Kinder mit Keimen haben, desto besser ist das für ihr Immunsystem. Doch so einfach ist das nicht, wie ein internationales Forschungsteam rund um den Epidemiologen Markus Ege herausgefunden hat. Man hat sich dafür die Untersuchungsergebnisse von über 1000 Grundschulkindern aus Europa angesehen. Die Forschenden untersuchten auch den Staub, der in den Wohnungen und Ställen lag.\n\nDas Ergebnis: Entscheidend für die schützende Wirkung ist nicht die Menge, sondern die Art der Mikroorganismen – und vor allem ihre Stoffwechselprodukte. Wenn diese eingeatmet werden, hemmen sie bestimmte Entzündungsprozesse im Körper. Das findet bereits in den ersten Lebensjahren statt, so Ege. Die Daten der Grundschulkinder zeigen das. Das Immunsystem eines Kindes profitiert möglicherweise bereits dann, wenn sich seine Mutter vor der Geburt regelmäßig auf einem Bauernhof aufhält.\n\nDie wichtigste Botschaft des Forschungsteams ist aber: Nicht der Bauernhof an sich ist wichtig, sondern bestimmte Mikroorganismen, die dort vorkommen. Studienleiter Ege sagt: Langfristig will man ihren Schutz medizinisch nachbilden. Daraus könnten dann irgendwann bessere Behandlungsmöglichkeiten für Asthma, Heuschnupfen und Neurodermitis entstehen – „aber eben nicht bald“, erklärt Ege.",
