      "id": "l-78355734",
      "title": "Kommen Wehrdienst und Zivildienst zurück?",
      "date": "2026-08-14",
      "transcript": "Kommen Wehrdienst und Zivildienst zurück?\n\nSeit 2011 ist die Wehrpflicht in Deutschland kein Thema mehr. Doch inzwischen hat sich die Weltpolitik sehr verändert. Die Bundeswehr braucht mehr Personal – und der Wehrdienst könnte wieder zur Pflicht werden.\n\nFrüher gab es in Deutschland die Wehrpflicht: Alle gesunden jungen Männer mussten als Soldaten zur Bundeswehr. Dort leisteten sie einige Monate Wehrdienst und bekamen eine militärische Grundausbildung. Doch in Deutschland darf niemand zum Dienst an der Waffe gezwungen werden. Deshalb gab es für die sogenannten Kriegsdienstverweigerer als Ersatz den Zivildienst. Die „Zivis“ arbeiteten zum Beispiel in Krankenhäusern, Pflegeheimen oder Schulen.\n\n2011 wurde die Wehrpflicht ausgesetzt, aber nicht ganz abgeschafft. Wer will, kann seitdem freiwillig zur Bundeswehr gehen oder einen Freiwilligendienst im sozialen Bereich leisten. Die neuen Bedrohungen von außen machen es aber notwendig, dass die Bundeswehr eine größere Truppe bekommt. Deshalb schickt die Bundesregierung seit 2026 allen 18-jährigen Männern einen Fragebogen. Darin müssen sie angeben, ob sie sich einen Dienst an der Waffe vorstellen könnten. Noch ist er freiwillig.\n\nDoch sollte es bald wieder eine Wehrpflicht geben, kommt auch der Zivildienst zurück. Darauf bereitet sich die Regierung jetzt vor – zusammen mit Sozialverbänden und -organisationen. Die könnten junge Mitarbeiterinnen und Mitarbeiter zwar sehr gut gebrauchen, warnen aber auch: Ein Zivildienst wird den schweren Personalmangel im sozialen Bereich nicht beheben. Stattdessen fordert man bessere Bedingungen für Freiwilligendienste.\n\nAuch die Opposition im Bundestag ist gegen eine neue Pflicht zum Wehr- oder Zivildienst. So sagt Ines Schwerdtner von der Partei Die Linke, dass man „jungen Menschen nicht vorschreiben darf, wie sie ein Jahr ihres Lebens zu verbringen haben“. Die Pflicht würde aber vielleicht nur für junge Männer gelten, denn für Frauen sind Wehr- und Zivildienst zumindest bisher immer freiwillig gewesen – und den Dienst an der Waffe dürfen sie überhaupt erst seit 2001 leisten.",
