      "id": "l-78265387",
      "title": "Der Handel mit afrikanischen Ameisen",
      "date": "2026-08-07",
      "transcript": "Der Handel mit afrikanischen Ameisen\n\nAmeisen werden als Haustiere immer beliebter – vor allem exotische Arten. Doch der Handel ist kaum geregelt und hat Folgen für die Ökosysteme in Afrika, und die Infrastruktur in Europa.\n\nDie Große Afrikanische Ernteameise lebt eigentlich in ostafrikanischen Ländern wie Kenia. Aber in Europa liegt sie besonders bei jungen Menschen als Haustier im Trend. Bestellen lassen sich die Tiere ganz einfach in Onlineshops, geliefert werden sie per Post. Wie die Ameisen zunächst nach Europa kommen, ist oft nicht klar. Laut internationalem Artenschutzabkommen CITES gelten Ameisen nicht als bedrohte Art. Der weltweite Handel ist damit weder untersagt noch genau geregelt.\n\nIn Kenia ist die Ausfuhr von Wildtieren – und damit auch Ameisen – generell verboten. Trotzdem wird immer wieder versucht, sie zu schmuggeln. Denn der Handel mit den kleinen Tieren ist ein lukratives Geschäft: Eine Königin der Großen Afrikanischen Ernteameise kann mehr als 200 Euro wert sein und lässt sich relativ leicht im Handgepäck transportieren. Mit härteren Strafen will das Land abschrecken und die Tiere besser schützen. Erst 2025 mussten vier Männer rund 5000 Euro Strafe zahlen, weil sie 5500 Ameisenköniginnen nach Europa bringen wollten.\n\nDer Biologe Chris Shepherd warnt, dass die Ausfuhr von Ameisen Folgen für die Ökosysteme in den Herkunftsländern hat. Werden Königinnen aus den Ländern gebracht, fehlen später ganze Ameisenkolonien. Und wichtige Aufgaben, wie der Transport von Samen, können nicht mehr von den Insekten übernommen werden. Shepherd fordert deshalb strengere Regeln für den internationalen Handel.\n\nDie meisten Ameisen kommen zwar nicht über den Onlinehandel, sondern über Pflanzenimporte nach Europa. Trotzdem kann man nicht ausschließen, dass auch Haustierkolonien ausgesetzt werden, erklärt Shepherd. Und vor allem in Süddeutschland merkt man jetzt schon, was eingeschleppte Ameisenarten anrichten können: Dort verursachen Große Drüsenameisen, die ursprünglich aus dem Mittelmeerraum und Nordafrika stammen, Probleme. Durch Kolonien in Verteilerkästen fallen immer mal wieder der Strom und das Internet aus.",
