      "id": "l-78084081",
      "title": "Darum gibt es Massentourismus",
      "date": "2026-07-24",
      "transcript": "Darum gibt es Massentourismus\n\nSo viele Menschen wie noch nie fahren in Urlaub. Besonders die Mittelmeerküste ist bei Touristinnen und Touristen beliebt. Doch was macht einen Ort eigentlich zu einem beliebten Urlaubziel?\n\nEinmal im Leben den Eiffelturm in Paris sehen oder die Sagrada Familia in Barcelona: Für Millionen Menschen ist das ein Traum – und immer mehr können ihn sich auch erfüllen. Laut der Tourismusorganisation der Vereinten Nationen waren 2025 1,5 Milliarden Touristinnen und Touristen in der Welt unterwegs – so viele wie noch nie. Nach Europa reisten knapp 800 Millionen Menschen.\n\nDie meisten Menschen wollen aber nicht in Städten Urlaub machen: „Zwei Drittel des weltweiten Tourismus gehen [...] an die Sonnenstrände des Südens“, so Historiker Hasso Spode. Viele fahren zum Beispiel nach Griechenland, Kroatien oder auf die Balearen. Dort gibt es viel Sonne und gute Bademöglichkeiten. Das reicht oft schon, damit viele Touristinnen und Touristen kommen, sagt Spode. Doch warum sind Orte wie Mallorca so beliebt und andere nicht?\n\nWichtig sind vor allem die richtige Infrastruktur und eine gute Anbindung. So war es schon im 19. Jahrhundert. 1841 wurde in Großbritannien eine Eisenbahnlinie von London bis zum Küstenort Brighton gebaut. Vorher verbrachte dort die Königsfamilie ungestört ihre Freizeit. Mit der Zugverbindung wurde Brighton aber plötzlich zu einem touristischen Hotspot, sagt Spode: „Die Royals traten die Flucht an, heute geht es dort zu wie am Ballermann.“\n\nAuch für Mallorca gilt: Entscheidend für den Tourismusboom ab den 1960er-Jahren war die gute Erreichbarkeit. Mittlerweile werden am Flughafen Palma de Mallorca jährlich über 30 Millionen Urlaubsgäste abgefertigt. Auch gutes Marketing spielt eine Rolle. Aber: Der Ort muss auch wirklich etwas zu bieten haben. Spode sagt: „Man kann nicht beliebig Destinationen kreieren.“ Relativ neu ist der Einfluss sozialer Medien auf den Tourismus: Ein besonderer Aussichtspunkt, eine einsame Badebucht, Drehorte beliebter Serien: Über Nacht werden manche Orte zu Hotspots, die von tausenden Touristen überrannt werden.",
