      "id": "l-77504846",
      "title": "Wie politisch ist die Fußball-WM 2026?",
      "date": "2026-06-12",
      "transcript": "Wie politisch ist die Fußball-WM 2026?\n\nEndlich wieder WM! Fans und Spieler freuen sich weltweit auf die Spiele in Mexiko, Kanada und den USA. Doch es gibt auch viel Kritik – dabei geht es unter anderem um Einreiseregeln und Umweltfragen.\n\nBei der diesjährigen Fußball-Weltmeisterschaft der Männer ist einiges anders als sonst: Zum ersten Mal findet sie in drei Ländern gleichzeitig statt. Und es nehmen 48 statt 32 Teams teil, sodass es 104 statt 64 Spiele geben wird. Wegen der großen Entfernungen zwischen den Stadien in den USA, Kanada und Mexiko müssen Spieler und Fans viel reisen, meist mit dem Flugzeug. Laut Studien könnte die WM mehr als neun Millionen Tonnen CO₂ verursachen. Deshalb bezeichnen Umweltverbände sie bereits als die möglicherweise „klimaschädlichste WM der Geschichte“.\n\nAuch von Menschenrechtsorganisationen kommt viel Kritik. Sie warnen vor allem vor Problemen bei der Einreise in die USA. Fans aus dem Iran oder aus Haiti dürfen wegen verschärfter Einreiseregeln nicht ins Land und können ihre Teams deshalb nicht vor Ort unterstützen. Auch Menschen aus Ländern wie der Elfenbeinküste oder dem Senegal erhalten nur schwer ein Visum. Und Fans aus migrantischen Communitys berichten, dass sie aus Angst vor den aggressiven Kontrollen in den USA lieber nicht zu den WM-Spielen reisen wollen.\n\nDass diese Sorgen begründet sind, zeigt auch der Fall des somalischen FIFA-Schiedsrichters Omar Artan. Der 34-Jährige sollte als erster Schiedsrichter aus seinem Land bei einer WM Spiele leiten. Doch ihm wurde trotz gültigem Visum nach seiner Ankunft am Flughafen in den USA die Einreise verweigert. Ciise Aden Abshir vom somalischen Sportministerium sagt dazu: „Ihn daran zu hindern, geplante Spiele zu leiten, schadet nicht nur ihm persönlich, sondern untergräbt auch das Bekenntnis des Fußballs zu Fairness, Leistung und Fairplay.“\n\nZum Start der WM 2026 steht deshalb nicht nur der Sport im Mittelpunkt, sondern auch die Frage, wie offen das Gastgeberland USA für Spieler und Fans aus aller Welt ist. Und ob politische Konflikte die Spiele beeinflussen – vor allem wegen der Spannungen zwischen dem Iran und den USA. Denn auch das ist neu: Noch nie zuvor fand eine Fußball-Weltmeisterschaft in einem Land statt, das sich im Krieg mit einem der WM-Teilnehmer befindet.",
