      "id": "l-77471403",
      "title": "„Vergessene Konten“: Wem gehört das Geld?",
      "date": "2026-06-09",
      "transcript": "„Vergessene Konten“: Wem gehört das Geld?\n\nIn Deutschland liegen Milliarden Euro auf Konten, die keinem mehr zugeordnet werden können. Auch die Erben wissen oft nichts Genaues und kommen nur schwer an Informationen. Experten fordern andere Regeln.\n\nStirbt ein Mensch, hinterlässt er oft Bankkonten oder Wertpapiere. Doch nicht immer wissen die Erben davon oder sie haben Schwierigkeiten, das Geld nach dem Tod zu bekommen. In Deutschland liegen laut einem Bericht des Forschungsministeriums aus dem Jahr 2021 mehr als vier Milliarden Euro auf sogenannten „vergessenen Konten“. Die genaue Summe ist nicht bekannt, auch weil Banken keine Zahlen veröffentlichen, wenn über längere Zeit nicht mehr auf die Konten zugegriffen wird.\n\nRechtlich ist die Lage eindeutig: Das Geld auf diesen Konten gehört weiterhin den ursprünglichen Eigentümern oder ihren Erben. Das heißt: Die Banken sind verpflichtet, solche Konten für unbestimmte Zeit zu führen, auch wenn niemand aktiv darauf zugreift. Der Staat wird nur dann Eigentümer, wenn er selbst Erbe ist.\n\nFür Privatpersonen ist es aber oft schwierig, solche Konten überhaupt zu finden. Häufig wissen sie nicht, bei welchen Banken der Verstorbene Konten oder Wertpapiere hatte. Deshalb müssen sie selbst bei einzelnen Bankenverbänden anfragen. Das ist nicht nur teuer, sondern auch kompliziert, weil Banken wegen des Datenschutzes nur wenig Auskunft geben dürfen. Außerdem ist oft nicht klar, ob es überhaupt Vermögen auf Banken gibt. „Aus diesem Grund entscheiden sich viele Erben dagegen, solche Anfragen zu machen“, sagt Beatrice Eisenschmidt vom Verband Deutscher Erbenermittler (VDEE).\n\nFinanzexperten fordern schon lange ein zentrales öffentliches Register, in dem Erben nach Informationen zu „vergessenem Vermögen“ suchen können. In anderen Ländern, zum Beispiel in Frankreich oder der Schweiz, gibt es öffentliche Datenbanken mit bestimmten Fristen. Und in Irland müssen Banken nach 15 Jahren Hinweise in zwei Zeitungen veröffentlichen. Meldet sich niemand, werden die Gelder für soziale Projekte verwendet. Erben können das Geld jedoch weiterhin zurückfordern.",
