      "id": "wieso-immer-weniger-kinder-schwimmen-k-nnen",
      "title": "Wieso immer weniger Kinder schwimmen können",
      "date": "2026-06-05",
      "transcript": "Wieso immer weniger Kinder schwimmen können\n\nIn Deutschland können viele Kinder nicht sicher schwimmen. Gründe dafür sind vor allem Geld- und Personalmangel. Ein neues Projekt bringt den Schwimmunterricht an Schulen und hilft besonders Kindern aus armen Familien.\n\nGibt es etwas Schöneres, als an einem heißen Sommertag ins kühle Wasser zu springen? Für viele Kinder wäre das jedoch lebensgefährlich. „Etwa 60 Prozent der Grundschülerinnen und -schüler in Deutschland können nicht sicher schwimmen“, sagt Martin Holzhause von der Deutschen Lebens-Rettungs-Gesellschaft (DLRG). Und 20 Prozent der Kinder können nach der Grundschule sogar überhaupt nicht schwimmen. Laut der Weltgesundheitsorganisation (WHO) ertrinken in Europa jedes Jahr rund 20.000 Menschen, in Deutschland waren es 2024 über 400.\n\nWoran liegt das? Ein Grund ist der schlechte Zustand der Schwimmbäder. Viele mussten schließen. Es fehlt vor allem Geld und Personal. Hinzu kommt die finanzielle Lage vieler Familien. Wolfgang Schmitz vom Kreissportbund Düren meint: Manche Kinder haben nicht einmal Badesachen oder ein Handtuch. Fast die Hälfte der Kinder, die nicht schwimmen können, kommen aus Haushalten mit weniger als 2500 Euro Nettoeinkommen im Monat. Schwimmkurse sind für zahlreiche Familien zu teuer.\n\nMehr Schwimmunterricht an Schulen könnte helfen, doch auch Schulen sind meist auf öffentliche Schwimmbäder angewiesen. Hier setzt ein neues, durch Spendengelder finanziertes Projekt an: „Mobi“ heißt ein mobiler Schwimmcontainer, der jeweils für drei Monate an einer Schule steht. Pro Woche nutzen ihn 500 bis 600 Kinder. Das Becken ist 40 Quadratmeter groß, hat eine Gegenstromanlage und alles, was ein normales Schwimmbad auch hat, berichtet Gero Wiesenhöfer vom Förderverein der Sparkasse KölnBonn.\n\nProjektleiterin Verena von der Gathen will so den Kindern helfen, die sonst „gar keine Möglichkeit haben“. Im Container können sie ihre Angst vor dem Wasser verlieren. Wiesenhöfer ergänzt: „Bis ein neues Schwimmbad gebaut ist, dauert es sehr lange. Bis dahin können wir etwas tun. Wenn es uns gelingt, in der Zeit ein Kind vor dem Ertrinken zu retten, dann haben wir alles richtig gemacht.“",
