      "id": "l-77239097",
      "title": "Wie helle Nächte der Natur schaden",
      "date": "2026-05-22",
      "transcript": "Wie helle Nächte der Natur schaden\n\nBei Dunkelheit helfen uns unzählige Lampen und Leuchten, den Weg zu finden und uns sicher zu fühlen. Doch die zunehmende Beleuchtung der Welt ist schon lange zum Problem für Mensch und Natur geworden.\n\nUnsere Nächte werden immer heller: Straßenbeleuchtung, Autoscheinwerfer, Licht in Schaufenstern, auf Baustellen, an Haltestellen, auf Parkplätzen, in Sportstadien, auf Werbeflächen. Laut einer Studie aus den USA sind die Lichtemissionen zwischen 2014 und 2022 weltweit um 16 Prozent gestiegen. Außerdem ist das Licht um etwa neun Prozent stärker geworden. Dabei kann zu viel Kunstlicht unseren Schlaf-Wach-Rhythmus stören, mit negativen Folgen für unsere Gesundheit. \n\nUnd nicht nur der Mensch leidet: Auch Tiere und Pflanzen haben sich über Millionen von Jahren an den natürlichen Wechsel von Licht und Dunkelheit angepasst. Störungen können fatal sein – zum Beispiel für Milliarden Insekten, die jedes Jahr bis zur Erschöpfung künstliche Lichter umkreisen und schließlich sterben. Oder für Zugvögel, die Mondlicht zur Orientierung brauchen. Nachtaktive Tiere wie Igel oder Fledermäuse meiden Licht, sodass ihr Lebensraum immer kleiner wird. \n\nIn Europa, wo es im weltweiten Vergleich viel künstliches Licht gibt, gibt es bereits Gesetze gegen Lichtverschmutzung. Als erstes Land weltweit beschloss Tschechien 2002 ein solches Gesetz. Dort dürfen Straßenlampen zum Beispiel nur noch nach unten strahlen. Frankreich hat es sogar geschafft, seine Lichtemissionen um 33 Prozent zu reduzieren. Hier müssen viele Lichtquellen um ein Uhr nachts ausgeschaltet werden. In Deutschland gibt es noch kein einheitliches Gesetz, aber das Bundesnaturschutzgesetz soll in diesem Sinne geändert werden. \n\nBis dahin empfehlen Umweltorganisationen, nur Flächen zu beleuchten, die wirklich hell sein sollen. Außerdem ist wärmeres Licht weniger schädlich als kaltes. Und auch die Zeit spielt eine Rolle: Das Licht sollte nur an sein, wenn es gebraucht wird. Dabei können zum Beispiel Bewegungsmelder helfen. Und wer abends die Vorhänge zuzieht, schützt nicht nur sich selbst vor Licht von außen, sondern stört auch keine nachtaktiven Tiere draußen.",
