      "id": "l-77213750",
      "title": "Neonazis in Berlin: Die Gewalt nimmt zu",
      "date": "2026-05-19",
      "transcript": "Neonazis in Berlin: Die Gewalt nimmt zu\n\nDeutschland wird gefährlicher: Das spüren viele Frauen, queere Menschen, Migrantinnen und Migranten und politisch Engagierte. Denn Alltagsrassismus und rechte Gewalt nehmen zu – auch in Berlin.\n\nAnne möchte nicht mit ihrem richtigen Namen genannt werden, denn sie wird zu oft von Neonazis angefeindet. Sie engagiert sich im Berliner Stadtteil Marzahn-Hellersdorf gegen rechte und rassistische Gewalt. Hier werden Menschen bedroht, weil sie pinkfarbene Haare haben, erzählt sie. Andere verstecken sich vor rechten Jugendlichen oder werden zusammengeschlagen. „Und man überlegt sich dreimal, wie man sich anzieht, wenn man jung und gegen Nazis ist.“\n\nSeit Jahren versuchen junge Neonazis in Berlin Fuß zu fassen – vor allem auch in dem Hochhausviertel Marzahn-Hellersdorf. Im Alltag fallen rechtsextreme Sticker im Viertel auf. 2025 versuchten Neonazis, Teilnehmerinnen und Teilnehmer einer örtlichen Christopher-Street-Day-Veranstaltung anzugreifen. Zwei der Täter waren jünger als vierzehn Jahre.\n\nDer stellvertretende Bürgermeister, Gordon Lemm, kennt die Probleme. Er beobachtet bei vielen jungen Menschen einen Werte-Backlash: „Frauen sollen diesen Vorstellungen nach wieder eine traditionelle Rolle einnehmen und Männer sollen die Ernährer sein.“ Eine Folge: Queere Menschen trauen sich weniger, als queer erkennbar zu sein. Insgesamt beobachtet Lemm eine Kultur der Härte, in der die Menschen keine Opfer sein wollen.\n\nZu spüren bekommen diese Härte besonders Menschen wie Farzaneh, deren Familie aus Afghanistan kommt. Farzaneh ist im Iran aufgewachsen und lebt seit Jahren in Hellersdorf – obwohl sie hier im Alltag Rassismus erlebt. Auch ihre Mutter wurde regelmäßig von einer älteren Frau beleidigt, was Farzaneh gemeldet hat. Das schätzt sie an Deutschland, sagt sie: „Man kann sich wenigstens bei der Antidiskriminierungsstelle melden. Im Iran gibt es das nicht. Wenigstens kann man sich wehren.“ Und Anne und Farzaneh werden weiterkämpfen – gegen Hass und Hetze in ihrer Heimat Berlin.",
