      "id": "l-77133447",
      "title": "Wie ein Wal berühmt wurde",
      "date": "2026-05-12",
      "transcript": "Wie ein Wal  berühmt wurde\n\nIm März 2026 ist vor der deutschen Ostseeküste ein Buckelwal gestrandet . Die Versuche, ihn zu retten, haben wochenlang für viel Aufregung gesorgt. Doch warum interessierten sich so viele Menschen für ein einzelnes Tier?\n\nLaut offiziellen Angaben ist er 12,35 Meter lang, 3,20 Meter breit und 1,60 Meter hoch. Und er hat wochenlang ein Land in Atem gehalten. Im März 2026 war ein Buckelwal vor der Küste Mecklenburg-Vorpommerns gestrandet. Seitdem lag er im flachen Wasser der Ostsee, konnte sich nicht freischwimmen und war in Lebensgefahr.\n\nSchnell kamen zahlreiche Schaulustige an die Ostsee, die den Wal sehen wollten. Umweltschützer, Fachleute und Politiker stritten vor Ort darüber, wie man dem Buckelwal helfen könnte. Alles Mögliche wurde unternommen: Man bespritzte das entkräftete Tier mit Wasser, grub Rinnen ins Meer, durch die es sich freischwimmen sollte, und brachte es schließlich sogar mit einem Schlepper in Richtung Nordsee. Mal gab es Hoffnung, mal hieß es, der Wal würde sterben.\n\nUnd die Versuche, ihn zu retten, wurden zu einem Medienspektakel: Auf Social Media, im Fernsehen oder in Zeitungen gab es ständig neue Berichte über den Wal. Er bekam sogar einen Namen – Timmy. So wurde er schnell zum bekanntesten Tier Deutschlands. Andere Themen wie der US-Krieg gegen den Iran oder Wahlen in Deutschland traten dagegen für einige Zeit in den Hintergrund.\n\nDas sorgte auch für Kritik. So fragte der Biologe Christoph Bautz, ob ein havariertes Boot mit Geflüchteten in Deutschland ebenso viel Aufmerksamkeit bekommen würde: „Aber nein, das passiert nur, wenn ein Wal havariert. Krass.“ Und für den Autor Frank Schätzing spielten bei den Rettungsversuchen auch Schuldgefühle eine Rolle: Schließlich sind es die Menschen selbst, die viele Tiere töten – auch wenn Buckelwale heute nicht mehr vom Aussterben bedroht sind. Ob aber der gestrandete Wal noch lebt, ist unklar. Denn seitdem er Anfang Mai in der Nordsee freigelassen wurde, gab es kein Lebenszeichen mehr von ihm.",
