      "id": "l-77079737",
      "title": "„Metropolis“: Wenn Filme die Zukunft zeigen",
      "date": "2026-05-08",
      "transcript": "„Metropolis“: Wenn Filme die Zukunft zeigen\n\nVor rund 100 Jahren kam Fritz Langs Film „Metropolis“ ins Kino. Er zeigt eine Stadt im Jahr 2026 – und eine Zukunft mit sozialer Ungleichheit , Maschinen und der Angst vor künstlicher Intelligenz .\n\nEs ist kein besonders schönes Bild: Oben in der Stadt leben die Reichen in hohen Gebäuden aus Glas und Stahl. Unten schuften Arbeiter Tag und Nacht. Sie steuern die Maschinen, mit denen alles funktioniert. Dieses Bild stammt aus dem Film „Metropolis“ von 1927. Er zeigt eine Stadt im Jahr 2026. Regie führte Fritz Lang. Das Drehbuch schrieb Thea von Harbou. Viele visionäre Ideen aus dem Film sind heute überraschend aktuell.\n\nEiniges gehört inzwischen zum Alltag: zum Beispiel das Bildtelefon. Künstliche Intelligenz (KI) ist ebenfalls ein Thema: Eine Figur des Films ist die Roboterfrau Maria, die aussieht wie ein Mensch. Sie soll die Arbeiter manipulieren. Da niemand den Unterschied zwischen Mensch und Android erkennt, scheint der Plan zu gelingen. Die „Menschmaschine“ veranschaulicht schon vor einem Jahrhundert die heutige Angst, dass Maschinen die Menschen kontrollieren oder ersetzen könnten. Heute warnen Fachleute, dass die KI viele Arbeitsplätze zerstören könnte.\n\n„Metropolis“ hat spätere Filme beeinflusst: beispielsweise Ridley Scotts „Blade Runner“ von 1982, der das Jahr 2019 zeigt. Die Erde ist nach einer Klimakatastrophe verseucht und überbevölkert. Androiden übernehmen für die Menschen schwere Arbeiten auf anderen Planeten, damit sie dort leben können. Manche Roboter wehren sich aber gegen die Menschen. Auch in James Camerons Film „Terminator“ aus dem Jahr 1984 kämpfen Maschinen gegen Menschen.\n\nKönnen wir etwas aus diesen Filmen lernen? In „Metropolis“ zerstören die Arbeiter am Ende die Stadt, und viele Menschen sterben in einer großen Flut. Es gibt aber auch Hoffnung auf Versöhnung. Im Film „Terminator“ ist die Erde im Jahr 2029 nach einem Atomkrieg verwüstet, und es gibt nur wenige Überlebende. Eine Gemeinsamkeit haben die Filme jedoch: Sie stellen die Frage, welche Zukunft wir wollen.",
