      "id": "l-76967766",
      "title": "Sorge um die Rente in Deutschland",
      "date": "2026-04-28",
      "transcript": "Sorge um die Rente in Deutschland\n\nIhr ganzes Berufsleben zahlen Arbeitnehmerinnen und Arbeitnehmer in die gesetzliche Rentenversicherung ein. Das Ziel ist, im Alter genug Geld zu haben. Doch viele Menschen fragen sich, ob ihre Rente ausreichen wird.\n\n„Die Rente ist sicher.“ Mit diesem Versprechen des früheren Bundesarbeitsministers Norbert Blüm machte die CDU in den 1980er-Jahren Wahlkampf. Heute glauben jedoch viele Menschen nicht mehr daran: Sie haben Angst vor Altersarmut. Bundeskanzler Friedrich Merz hat 2026 sogar gewarnt: Die Rente wird „nicht mehr ausreichen, auf Dauer den Lebensstandard zu sichern.“\n\nEine Untersuchung der OECD in 38 Staaten zeigt: In Deutschland beträgt die Nettorente eines männlichen Arbeitnehmers etwa 53 Prozent des letzten Einkommens – wenn er sein ganzes Arbeitsleben lang Rentenbeiträge gezahlt hat. Verglichen mit anderen Ländern ist das ein unterdurchschnittlicher Wert: In Frankreich beträgt die Nettorente 70, in Spanien sogar über 80 Prozent. Schwierig ist die Situation dadurch vor allem für Menschen mit niedrigem Einkommen. Auch aus anderen Gründen kann der Rentenanspruch vermindert sein, zum Beispiel wenn man viele Jahre nicht gearbeitet hat – etwa weil man sich um seine Kinder gekümmert hat oder arbeitslos war.\n\nDas deutsche Rentensystem funktioniert nach dem Umlageverfahren: Arbeitnehmerinnen und Arbeitnehmer bezahlen mit ihren Beiträgen die Renten derjenigen, die heute alt sind oder aus anderen Gründen nicht mehr arbeiten können. Fachleute warnen, dass dieses System in Zukunft nicht mehr funktionieren könnte. Denn einerseits werden in Deutschland seit vielen Jahren immer weniger Kinder geboren, andererseits gibt es immer mehr Rentnerinnen und Rentner.\n\nDie Bundesregierung diskutiert darüber, wie das Rentensystem langfristig gesichert werden kann. Der Bundeskanzler spricht sich dafür aus, die private Altersvorsorge zu stärken, etwa durch Aktien. Aktien unterliegen jedoch auch Kursschwankungen. Die Höhe der späteren Auszahlung ist daher unklar. Die Rente – bei vielen Menschen sorgt sie zunehmend für Verunsicherung.",
