      "id": "l-76882582",
      "title": "Fußball, Frauen und Diskriminierung",
      "date": "2026-04-21",
      "transcript": "Fußball, Frauen und Diskriminierung\n\nSexismus und Rassismus sind im Fußball immer noch Alltag – im Stadion wie in den sozialen Medien. Nun gibt es in der 1. Fußball-Bundesliga der Männer zum ersten Mal eine Cheftrainerin. Auch sie erlebt Diskriminierung.\n\nMarie-Louise Eta hat Geschichte geschrieben: Eine Cheftrainerin hat es in der Fußball-Bundesliga der Männer noch nie gegeben. Zwar besitzen laut Deutschem Fußballbund fast 4000 Frauen eine Fußball-Trainerlizenz. Aber bisher haben nur 33 eine Lizenz als Cheftrainerin für die 1. und 2. Bundesliga. Neben viel Unterstützung für Eta und ihren Verein Union Berlin gibt es in den sozialen Medien auch sexistische und diskriminierende Kommentare. Diese sagen allerdings mehr über ihre Verfasser aus als über die, die damit beleidigt werden, so Eta.\n\nRobin Afamefuna, Profifußballer und Kulturanthropologe, beschäftigt sich in seiner Forschung mit Sexismus und Rassismus im Fußball. Der Sohn eines nigerianischen Vaters und einer deutschen Mutter erlebt selbst immer wieder Diskriminierung. „Wir haben im Fußball oftmals die Diskussion, ob das Stadion als ein sicherer Raum wahrgenommen wird“, erzählt er. Vor allem weiße Männer glauben häufig, dass Aussehen und Herkunft im Stadion egal sind. Doch Afamefuna sagt: „Das stimmt einfach nicht!“\n\n„Wir leben in einer Gesellschaft, die sehr patriarchal geprägt ist. In dieser Gesellschaft wird oftmals die weiße, männliche Perspektive als die Norm angesehen“, so Afamefuna. „Und der Fußball ist sehr weiß und männlich dominiert.“ Es ist eine Kultur entstanden, in der Menschen im Stadion machen, was sie wollen: „Schreien, was sie wollen, rassistisch, sexistisch oder generell Spieler und Spielerinnen beleidigen.“ Viele wollen auch, dass es so bleibt: „Es ist wie ein Grundrecht für viele Menschen, diesen Raum zu haben, um dieses Verhalten zeigen zu dürfen.“ Damit sich daran etwas ändert, sind auch weibliche Vorbilder wichtig.\n\nDas weiß auch Marie-Louise Eta und kann durch ihre neue Tätigkeit „vielleicht Wege und Türen öffnen und Inspiration schaffen, damit auch junge Mädchen sehen, was alles möglich ist“. Noch wichtiger wäre Eta, wenn es die Frage nach dem Geschlecht im Fußball gar nicht mehr geben würde, „wenn es nur noch um den Sport geht und wenn es nur noch um Leistung geht – ganz unabhängig vom Geschlecht“.",
