      "id": "l-76644624",
      "title": "Haben Frauen weniger Finanzwissen?",
      "date": "2026-04-03",
      "transcript": "Haben Frauen weniger Finanzwissen?\n\nViele Frauen kümmern sich zu wenig um ihre Finanzen – mit negativen Folgen für ihr Vermögen und ihre Altersvorsorge. Doch woran liegt das und wie lässt sich das ändern?\n\nWeniger als die Hälfte der Menschen im Euroraum kann nach Umfragen der Europäischen Zentralbank (EZB) Fragen zu Zinsen, Inflation und Risikostreuung korrekt beantworten. Frauen schneiden dabei im Durchschnitt jedoch meist noch mal deutlich schlechter ab als Männer. Dieser Wissensrückstand zeigt sich seit über 20 Jahren in zahlreichen Untersuchungen. Und bis heute hat sich daran wenig geändert, sagt Tabea Bucher-Koenen vom Leibniz-Zentrum für Europäische Wirtschaftsforschung (ZEW). Auch nicht bei jungen Frauen mit guter Ausbildung und höherem Einkommen.\n\nDass Frauen jedoch oft mehr wissen, als sie sich selbst zutrauen, hat jetzt eine neue Analyse des ZEW gezeigt. Demnach wählen Frauen bei Finanzfragen überproportional häufig die Antwortoption „Ich weiß es nicht“ aus. Gibt es diese Antwortmöglichkeit nicht, schneiden sie sehr viel besser ab. „Etwa 30 Prozent der Unterschiede in der finanziellen Bildung zwischen den Geschlechtern sind auf mangelndes Selbstbewusstsein zurückzuführen“, so Bucher-Koenen:\n\nUrsachen für das fehlende Selbstbewusstsein und Wissen lassen sich Studien zufolge oft schon in der Kindheit finden: Eltern sprechen häufiger mit Jungen über Finanzthemen als mit Mädchen, weil sie erwarten, dass Jungen sich mehr dafür interessieren. Außerdem bekommen Mädchen im Durchschnitt später und weniger Taschengeld. Auch weil traditionelle Rollenbilder bis heute wirken und Finanzen bei vielen Menschen noch – so wie früher – als „Männersache“ gelten. In Deutschland etwa konnten Frauen erst ab 1958 ein eigenes Bankkonto eröffnen und bis 1977 konnte ein Ehemann entscheiden, ob seine Frau arbeiten gehen durfte.\n\nDamit mehr Frauen bei wichtigen Finanzentscheidungen aktiv werden und am Finanzmarkt selbstbewusster handeln können, braucht es laut Expertinnen und Experten eine bessere allgemeine Finanzbildung. Das hat auch die EZB erkannt. Sie will das Finanzwissen von Frauen unter anderem mit Videos oder Apps verbessern – auch aus eigenem Interesse. Denn ihre Geldpolitik kann nur gut wirken, wenn möglichst viele Menschen sie verstehen.",
