      "id": "l-76603904",
      "title": "Waren die eigenen Großeltern Nazis?",
      "date": "2026-03-31",
      "transcript": "Waren die eigenen Großeltern Nazis?\n\nMillionen NSDAP-Daten sind jetzt im US-Nationalarchiv online für alle zugänglich. Dort kann man prüfen, ob Familienmitglieder in der Partei waren. Die genaue Rolle muss aber weiter recherchiert werden.\n\nLaut dem Deutschen Historischen Museum waren 1945 8,5 Millionen Menschen NSDAP-Mitglieder. Waren auch die eigenen Großeltern dabei? Mehr als 80 Jahre nach dem Ende der NS-Herrschaft sind jetzt die Daten von rund 6,6 Millionen Deutschen online zugänglich. Im US-Nationalarchiv kann man in digitalisierten Karteikarten nach Parteimitgliedern suchen. Dort stehen Namen, Geburtsdaten, Partei-Eintrittsdaten und Mitgliedsnummern.\n\nDiese Daten findet man in Deutschland seit 1994 auch im Bundesarchiv. „Und dort bekommt man eigentlich auch noch sehr viel mehr Informationen als nur diese Mitgliedschaften“, erklärt der Historiker Johannes Spohr. Allerdings dürfen Informationen über eine Person erst 100 Jahre nach ihrer Geburt oder zehn Jahre nach ihrem Tod herausgegeben werden. Die Daten sind auch nicht online zugänglich, sondern müssen schriftlich beantragt werden. Man darf nur nach eigenen Verwandten suchen – und nicht zum Beispiel nach Nachbarn.\n\nEine Studie zeigt: Mehr als zwei Drittel der Deutschen glauben, dass ihre Vorfahren keine NS-Täter waren. Mit der Wirklichkeit hat das wenig zu tun. Für Spohr ist das eher ein Gefühl als konkretes Wissen. Denn nach dem Krieg wurde nur in wenigen Familien über die Verbrechen der Nazi-Zeit gesprochen – und schon gar nicht über die Rolle von Familienmitgliedern. Die deutsche Erinnerungskultur an die Nazi-Zeit gilt im Ausland als vorbildlich. Aber „tatsächlich wird es mit der Erinnerungskultur immer dann kompliziert, wenn es konkret wird, also wenn es wirklich bestimmte Personen betrifft, die man vielleicht auch noch kannte“, so Spohr. \n\nHeute wollen viele Menschen wissen, was ihre Verwandten in der NS-Zeit genau gemacht haben. Spohr sagt, dass inzwischen auch die Enkelgeneration und deren Kinder aktiv nachforschen. Wer einen Namen im US-Nationalarchiv entdeckt, steht aber erst am Anfang der eigentlichen Recherche. Denn die Karteikarten zeigen nur die NSDAP-Mitgliedschaft, nicht was die Menschen getan haben. Spohr sagt: „Und natürlich kann man auf schlimme Dinge stoßen, die den Familienerzählungen widersprechen.“",
