      "title": "Die SPD – Niedergang einer Arbeiterpartei",
      "date": "2026-03-17",
      "transcript": "Die SPD – Niedergang einer Arbeiterpartei\n\nDie älteste Partei Deutschlands ist lange Zeit auch eine der wichtigsten gewesen. Vier Bundeskanzler waren Sozialdemokraten. Doch heute verliert die Partei eine Wahl nach der anderen, die Zustimmung sinkt. Aber warum?\n\nFür Andreas Stoch war es einer „der schwärzesten Tage, die ich mir vorstellen konnte“. Er war der Spitzenkandidat der SPD bei der Landtagswahl in Baden-Württemberg am 8. März 2026. Das Ergebnis: gerade einmal 5,5 Prozent – fast wäre Stochs Partei nicht mehr im Parlament gewesen. Einen solchen Misserfolg hat es für die SPD in der Geschichte der Bundesrepublik Deutschland noch nie gegeben.\n\nDabei hat die SPD früher regelmäßig Wahlen gewonnen. In ihren besten Zeiten gaben ihr fast die Hälfte aller Wählerinnen und Wähler ihre Stimme. Gegründet wurde sie 1863 – mitten in der Zeit der Industrialisierung. Sie war eine Partei für die Arbeiterinnen und Arbeiter, deren Lebensbedingungen damals extrem schlecht waren: Die Arbeitstage waren lang, die Löhne niedrig; es gab noch keine Krankenversicherung und zu wenig Wohnungen. Die SPD versprach Bildung und Aufstieg für alle Menschen – und hatte damit sehr lange Erfolg.\n\nSeit 1998 ist die SPD fast ununterbrochen Teil der Bundesregierung. Doch in dieser Zeit begann auch ihr Niedergang – besonders unter dem früheren SPD-Bundeskanzler Gerhard Schröder. In einer Wirtschaftskrise mit hoher Arbeitslosigkeit beschloss seine Regierung 2003 harte Reformen: Man kürzte massiv Sozialleistungen, schuf viele schlecht bezahlte Jobs und baute die Leiharbeit aus. Daraufhin gab es große Proteste gegen Schröders Politik – tausende Parteimitglieder verließen die SPD.\n\nSeitdem werden die Wahlergebnisse der SPD – von einzelnen Ausnahmen abgesehen – immer schlechter. Untersuchungen zeigen: Wer sich gesellschaftlich abgehängt fühlt, wählt heute kaum noch SPD. Dafür gewinnen andere Parteien. So bekam die rechtsextreme Alternative für Deutschland (AfD) bei der Landtagswahl in Baden-Württemberg über 18 Prozent der Stimmen – in Thüringen ist sie sogar schon stärkste Partei. Und in der SPD hoffen viele Mitglieder, dass ihre Partei endlich wieder eine andere Politik macht.",
