      "id": "l-76292306",
      "title": "Wie viel Bildschirmzeit ist für Kinder in Ordnung?",
      "date": "2026-03-10",
      "transcript": "Wie viel Bildschirmzeit ist für Kinder in Ordnung?\n\n„Weniger ist besser“, sagen Fachleute zum Thema Bildschirmzeit bei Kindern. Denn wenn Kinder zu lange vor dem Bildschirm sitzen, fehlt ihnen die Zeit für wichtige Erfahrungen im echten Leben.\n\nTrotz vieler Studien gibt es international bisher keine einheitlichen Empfehlungen dazu, wie viel Zeit Kinder maximal vor dem Bildschirm verbringen sollten. Bei ein paar Grundsätzen sind sich Fachleute aus der Medizin, Psychologie, Suchtforschung und Medienpädagogik jedoch einig: Sie schauen zum Beispiel darauf, was Kinder in ihrer jeweiligen Entwicklungsphase brauchen. Und sie folgen dem Prinzip der Vorsorge und nehmen den wissenschaftlichen Verdacht ernst, dass Handys und Co. Schaden anrichten können. \n\nKinderärztin Ulrike Gaiser, Mitautorin der deutschen Medienleitlinie für Kinder, empfiehlt „Bildschirmfrei bis drei“. Denn kleine Kinder benötigen reale Erfahrungen, um die Umwelt kennenzulernen und Aufmerksamkeit und Geduld zu üben, so Gaiser. Die WHO ist da weniger streng. Sie empfiehlt ab dem zweiten Lebensjahr nicht mehr als eine Stunde Bildschirmzeit, sagt aber auch: „Weniger ist besser.“ Und Kinderpsychologin Julia Asbrand von der Universität Jena warnt: „Bei sehr jungen Kindern kann alles, was sie sehen, in ihrer Vorstellung echt sein“ – und das kann sie verunsichern. Bei zu viel Bildschirmzeit bleibt zudem weniger Zeit übrig für Sprache, Feinmotorik und soziale Interaktion.\n\nIn Deutschland gibt es Empfehlungen für Bildschirmzeiten je nach Alter: Im Kindergartenalter sollten es maximal 30 Minuten sein, und in den ersten Jahren der Grundschule höchstens 30 bis 45 Minuten, begleitet durch Erwachsene. Für 9- bis 12-Jährige gelten Richtwerte von 45 bis 60 Minuten, für 12- bis 16-Jährige maximal ein bis zwei Stunden, und für 16- bis 18-Jährige etwa zwei Stunden täglich.\n\nGanz so dogmatisch werden die Zahlen aber nicht gesehen. Fachleute sagen: Wichtiger als die Dauer ist der Inhalt – also was Kinder sehen – und wie sie es erleben und ob sie dabei begleitet werden. Ein kompletter Verzicht wäre weltfremd. Digitale Medien können zudem auch hilfreich sein, zum Beispiel beim Lernen oder um soziale Kontakte zu pflegen, so Gaiser. Entscheidend sind eine vertrauensvolle Eltern-Kind-Beziehung und klare Regeln, die Eltern selbst vorleben. Zum Beispiel: Um 8 Uhr gehen alle Handys ins Bett. Auch die der Eltern.",
