      "id": "l-76139595",
      "title": "Wenn Menschen Angst vor der Natur haben",
      "date": "2026-02-27",
      "transcript": "Wenn Menschen Angst vor der Natur haben\n\nEin Aufenthalt in der Natur ist gesund und reduziert Stress. Doch immer mehr Menschen haben Angst vor Bäumen und Tieren. Woran liegt das – und was hat das für Folgen?\n\nFür manche Menschen gibt es nichts Beruhigenderes als einen Spaziergang unter Bäumen. Forschungen beweisen, dass Waldaufenthalte helfen, Stress zu reduzieren, die Konzentration zu verbessern und die Gefühle auszugleichen. Eine aktuelle Studie der Universität Lund zeigt aber nun, dass immer mehr Menschen Angst vor der Natur haben. Der Wissenschaftler Johan Kjellberg Jensen begründet das damit, dass viele in Städten leben und im Alltag kaum noch Kontakt zur Natur haben.\n\nDie Menschen verbringen heute viel mehr Zeit in Innenräumen und beim Surfen in der digitalen Welt. Erfahrungen in der freien Natur fehlen oft. Diese Entwicklung kann in Zeiten von Klimawandel und Artensterben ein Problem sein. Die Psychologin Lea Dohm erklärt, dass man eher bereit ist, sich „für Umwelt-, Natur- und Klimaschutz“ einzusetzen, wenn man sich mit der Natur verbunden fühlt. Die Angst vor der Natur kann sogar zu Feindseligkeit führen, sodass manche Menschen das Töten wilder Tiere unterstützen.\n\nSchon in der Vergangenheit gab es Zeiten, in denen die Menschen Angst vor der Natur hatten. „Früher galt der Wald in Mitteleuropa als Ort der Gefahr“, sagt der Psychologe Dirk Stemper. Das änderte sich erst in der ersten Hälfte des 19. Jahrhunderts, als der Wald zum romantischen Ort erklärt wurde. Heute kommt die Angst vor der Natur zurück – allerdings nicht wegen wirklicher Gefahren, sondern durch Entfremdung und den Konsum digitaler Medien. Die virtuelle Natur wirkt für einige ‚echter‘ als der Wald und die Tiere vor der Tür.\n\nDie Umweltpädagogin Susanne Sigl hat festgestellt, dass viele Kinder weder Äste noch Insekten anfassen wollen und dass Erde für sie häufig als „Dreck“ gilt. Das kann zu einer Abwärtsspirale führen: Was uns nicht interessiert oder wovor wir Angst haben, wollen wir auch nicht schützen. Fachleute empfehlen, Kindern mehr Wissen über Tiere und Pflanzen zu vermitteln – und die direkte Konfrontation mit der Natur. „Wenn Kinder beim Fangen-Spiel im Wald hinfallen, sich hinter einem Baum verstecken […]“, sagt Susanne Sigl, „dann ist das Anfassen von Ästen danach meist kein Problem mehr.“",
