      "id": "l-76103353",
      "title": "Bauprojekte im Land der Verspätungen",
      "date": "2026-02-24",
      "transcript": "Bauprojekte im Land der Verspätungen\n\nIn Deutschland werden große Bauprojekte oft später fertig als geplant. Die Kosten steigen, das Vertrauen sinkt. Die Renovierung der Kölner Oper macht das sehr deutlich – und Notre-Dame in Paris zeigt, wie es besser geht.\n\n \n\nDas Projekt sollte nur drei Jahre dauern und 2015 beendet sein: die Renovierung der Kölner Oper. Mehr als zehn Jahre später ist das Gebäude immer noch nicht fertig. Die Kosten stiegen dabei von 250 auf 850 Millionen Euro. Inklusive Zinsen und weiterer Ausgaben muss man sogar mit 1,5 Milliarden rechnen. Die Opernsängerin Emily Hindrichs sagt: „Es fühlt sich an, als würde man Geld in ein Fass ohne Boden werfen.“ Als Gründe für die Verspätung nennt der Projektleiter Jürgen Marc Volm unter anderem die Komplexität des Projekts und die schlechte Kommunikation.\n\nDoch die Kölner Oper ist nur ein Beispiel für ein allgemeineres Problem in Deutschland: Große Bauprojekte geraten immer wieder in Schwierigkeiten, so etwa auch der neue Stuttgarter Hauptbahnhof. Reiner Holznagel vom Steuerzahlerbund meint: „Bauen in Deutschland ist sehr, sehr teuer, […] weil wir so viele Auflagen haben.“ Die Kontrolle liegt außerdem bei vielen Ämtern, was Prozesse zusätzlich verlangsamt. Damit verliert Deutschland sein früheres Ansehen als Land der Zuverlässigkeit, so Holznagel. Und die Probleme zeigen sich auch in der Infrastruktur: am Zustand von Brücken, Straßen und der Bahn.\n\nEin Blick nach Paris beweist, dass es auch anders geht. Nach dem Feuer am Dach der Kirche Notre-Dame im Jahr 2019 versprach Präsident Macron eine Wiedereröffnung nach fünf Jahren – und hielt Wort. Projektleiter Philippe Jost spricht vom „Geist von Notre-Dame“: ein kleines Team, viel Vertrauen und Kommunikation. Und: Man wählte nicht die billigsten, sondern die besten Firmen. Jost erklärt: „Wenn wir Geld ausgeben, um ein Problem schnell zu lösen, dann ist es gut investiert.“\n\nIn Köln hat Verspätung beim Bau eine lange Tradition. Der Kölner Dom brauchte über 600 Jahre bis zur Fertigstellung. Der Schauspieler Andreas Grötzinger hofft, „dass wir jetzt schneller sind“. Die Wiedereröffnung der Kölner Oper ist für Herbst 2026 geplant. Für Emily Hindrichs wird das ein großer Moment sein: „Wenn ich endlich dort singen darf, ist das wie eine Heimkehr. Darauf habe ich all die Jahre gewartet.“",
