      "id": "l-76003077",
      "title": "Deutschland lässt Taliban in Vertretungen zu",
      "date": "2026-02-17",
      "transcript": "Deutschland lässt Taliban in Vertretungen zu\n\nDie Botschaft in Berlin, die Generalkonsulate in München und Bonn: In Deutschland kontrollieren jetzt die Taliban afghanische Vertretungen – während die Bundesregierung mit dem Regime über Abschiebungen spricht.\n\nIm Oktober 2025 trat Hamid Nangialay Kabiri als Generalkonsul in Bonn zurück, nachdem mit Zustimmung Deutschlands Taliban-Mitarbeiter akkreditiert worden waren. „Ich sagte ihnen, dass ich nicht mit Terroristen arbeiten kann“, so Kabiri. „Jetzt gehört das Konsulat in Bonn den Taliban.“ Die kontrollieren Afghanistan seit 2021 und werden international für schwere Menschenrechtsverletzungen verurteilt. Über die afghanischen Vertretungen haben sie nun Zugang zu allen Daten afghanischer Staatsangehöriger in Deutschland.\n\nViele Afghaninnen und Afghanen in Deutschland sind vor dem Regime geflohen und haben daher Angst, die Vertretungen zu betreten. Doch sie sind abhängig von ihnen, zum Beispiel bei der Passbeschaffung: „Ohne gültige Pässe können sie ihren Aufenthalt nicht sichern, keine Arbeitsverträge verlängern und teilweise nicht einmal grundlegende Behördengänge erledigen“, so die Organisation VAFO.\n\nWährenddessen will die Regierung unter Bundeskanzler Friedrich Merz mehr Menschen nach Afghanistan abschieben – trotz der Menschenrechtsverletzungen im Land. Die Taliban scheinen das zu nutzen, um schrittweise diplomatische Anerkennung in Europa zu erlangen. 2025 reisten Mitarbeitende des deutschen Innenministeriums nach Afghanistan, um über Abschiebungen aus Deutschland zu sprechen. Laut dem Ministerium stimmten die Taliban grundsätzlich zu, alle afghanischen Staatsangehörigen zurückzunehmen. Im Januar 2026 bestätigte Innenminister Alexander Dobrindt die ersten Abschiebungen in das Land.\n\nFür Conrad Schetter vom Bonn International Centre for Conflict Studies handelt es sich dabei um einen „schmutzigen Deal“. Denn de facto bedeuten die Akkreditierungen die Anerkennung von Taliban-Vertretern als legitime afghanische Repräsentanten in diplomatischen Vertretungen. Auch der frühere afghanische Diplomat Kabiri fragt sich, welchen Sinn es macht, dass Deutschland Menschen zunächst Asyl gewährt, weil sie vor den Taliban fliehen – nur um sie dann wieder zu den Taliban zurückzuschicken. „Wo ist die Logik?“, fragt er.",
