      "id": "l-75894165",
      "title": "Die Bahn – ein gefährlicher Arbeitsplatz?",
      "date": "2026-02-10",
      "transcript": "Die Bahn – ein gefährlicher Arbeitsplatz?\n\nEin Mann hat in einem Zug einen Mitarbeiter der Deutschen Bahn tödlich verletzt. Das Entsetzen in Deutschland ist nach diesem Vorfall groß. Gewalt gegen Bahnpersonal ist aber schon länger ein Problem.\n\nFebruar 2026: In einem Zug der Deutschen Bahn gab es eine Fahrscheinkontrolle, ein Mann war ohne gültiges Ticket unterwegs. Ein Mitarbeiter der Deutschen Bahn forderte den Mann dazu auf, den Zug an der nächsten Haltestelle zu verlassen. Dann griff der Mann den Bahnmitarbeiter plötzlich an – und verletzte ihn so schwer, dass er später starb. Der mutmaßliche Täter wurde verhaftet.\n\nDie Statistik zeigt: Das Bahnpersonal hat keinen ungefährlichen Job. Im Jahr 2025 wurden etwa 3000 Mitarbeiterinnen und Mitarbeiter der Bahn Opfer von Straftaten. Laut Jonas Rees, Professor für Politische Psychologie an der Universität Bielefeld, hat die Gewalt seit 2015 immer mehr zugenommen. Die Angestellten werden Tag für Tag „beschimpft, beleidigt, bedroht oder eben auch körperlich angegriffen“, sagt er.  Manche trauen sich inzwischen nicht einmal mehr, Tickets überhaupt zu kontrollieren.\n\nIn einer Studie zum Thema erforschte Rees die Ursachen der Gewalt – und fand heraus: Fahrgäste werden eher dann gewalttätig, wenn sie Alkohol getrunken haben oder die Züge überfüllt oder verspätet sind. Außerdem gibt es am Wochenende mehr Angriffe gegen das Bahnpersonal als unter der Woche. Und es spielt eine Rolle, dass die Mitarbeiterinnen und Mitarbeiter Uniform tragen. Wenn es Probleme gibt, werden sie oft wegen ihrer Berufskleidung „stellvertretend [...] für die Bahn“ angegriffen, so Rees.\n\nDer Tod des Bahnmitarbeiters hat in ganz Deutschland für Entsetzen gesorgt. Bundesinnenminister Alexander Dobrindt forderte kurz nach der Tat eine Strafe „mit der vollen Härte des Gesetzes“ und will die Mindeststrafen erhöhen. Für Rees ist das aber keine Lösung. Der Gewaltforscher findet: Mit Prävention und Deeskalation erreicht man mehr. Dazu gehört für ihn auch mehr Sicherheitspersonal. Und generell könnten Drehkreuze am Bahnsteig die Fahrscheinkontrolle ersetzen. Außerdem sollten sich Schutzräume für Mitarbeitende an Bord der Züge befinden, die sie im Notfall nutzen können.",
