      "id": "l-75822001",
      "title": "Stadt der Zukunft: mehr Grün, weniger Parkplätze?",
      "date": "2026-02-06",
      "transcript": "Stadt der Zukunft: mehr Grün, weniger Parkplätze?\n\nParkplätze brauchen viel Platz, doch der ist besonders in Großstädten knapp. Deshalb gehen manche Städte wie zum Beispiel Wien neue Wege. Dort werden Parkplätze zu Grünflächen – zur Freude der meisten Einwohner.\n\nWer in einer Großstadt einen Parkplatz braucht, weiß: Das kann ewig dauern – in Los Angeles zum Beispiel suchen Menschen durchschnittlich mehr als 80 Stunden pro Jahr nach einem Parkplatz. Doch mehr Parkfläche bedeutet auch mehr Asphalt, der Hitze speichert und Regenwasser nicht versickern lässt. Für Städte heißt das: mehr Wärme und höhere Überschwemmungsgefahr. Deshalb werden zum Beispiel in der österreichischen Hauptstadt Wien keine neuen Parkplätze mehr gebaut. Aus vielen alten Parkplätzen entstehen Parks oder öffentliche Plätze.\n\nSeit 2022 gibt es in Wiens Innenstadt keine kostenlosen Parkplätze mehr, und Besucherinnen und Besucher dürfen nur zwei Stunden parken. Dafür hat man mehr Park-and-Ride-Plätze außerhalb der Innenstadt eingerichtet, die direkt mit dem öffentlichen Verkehr verbunden sind. „Man muss eine günstige und bessere Alternative anbieten“, so Ina Homeier vom Wiener Stadtplanungsamt. In Wien helfen dabei die Einnahmen aus den höheren Parkgebühren.\n\nDass Städte Parkplätze jetzt wieder abschaffen wollen, „ist politisch sehr heikel“, erklärt der amerikanische Autor Henry Grabar, der ein Buch über Parkplätze in amerikanischen Städten geschrieben hat. Viele Autofahrer und Autofahrerinnen fühlen sich dadurch angegriffen – besonders in den USA, wo 92 Prozent der Haushalte mindestens ein Auto haben. Trotzdem gibt es auch hier Beispiele für Veränderung: In Dallas ist kürzlich ein großer Innenstadtparkplatz zu einem 3,7 Hektar großen Park geworden. \n\n„Wir müssen die Menschen mit ins Boot holen. Wir müssen fragen: Wie soll Ihr Stadtviertel aussehen? […]“, sagt Ina Homeier. Deshalb dürfen die Wienerinnen und Wiener mitentscheiden, ob aus einzelnen Parkplätzen Gärten oder Spielplätze werden. Das wirkt: Im Vergleich zu den 1990er-Jahren nutzen Wienerinnen und Wiener das Auto heute 37 Prozent weniger. Und Umfragen zeigen, dass mehr als zwei Drittel der Bevölkerung für weniger Parkplätze und mehr Grünflächen sind.",
