      "id": "l-75716040",
      "title": "Wie klug sind unsere Kühe?",
      "date": "2026-01-30",
      "transcript": "Wie klug sind unsere Kühe?\n\nIn Österreich zeigt Kuh Veronika ein besonderes Verhalten: Sie benutzt Werkzeuge und überrascht damit die Forschung. Die Entdeckung könnte vieles verändern. Sind einige Tiere vielleicht klüger, als wir denken?\n\nDie 13 Jahre alte Kuh Veronika aus dem Dorf Nötsch in Österreich überrascht die Forschung. Sie benutzt Werkzeuge, um sich zu kratzen – und das sogar auf unterschiedliche Art und Weise, je nachdem, welches Körperteil sie damit erreichen will. Ein solches Verhalten haben Forschende bis jetzt nur bei Schimpansen beobachtet. Als die Wiener Verhaltensforscherin Alice Auersperg durch ein Video auf die Kuh aufmerksam wurde, beschlossen sie und ihr Kollege Antonio Osuna‑Mascaró deshalb, sich Veronika einmal genauer anzuschauen.\n\nDie beiden wollten sich sicher sein, dass Veronika kein Deepfake war. „Wir können einer Anekdote nicht einfach so glauben“, so die Forscherin. Doch Veronika ist tatsächlich echt: Die Kuh lebt bei Familie Wiegele und hat viel Abwechslung auf ihrer Weide. Wenn niemand da ist, um sie zu kraulen, nimmt sie einfach einen Besen oder einen Stock. Osuna‑Mascaró blieb gleich mehrere Wochen in Nötsch und führte 70 Versuche mit Veronika durch. Dabei stellte er fest, dass die Kuh ihre Werkzeuge „auf sinnvolle Weise“ einsetzt: Je nach Zweck benutzt Veronika gezielt die verschiedenen Enden des Besens, wie Osuna‑Mascaró erklärt.\n\nWie Veronika ihre Werkzeuge am eigenen Körper gebraucht, haben die beiden Forschenden nun in einer Studie beschrieben. Ihre Beobachtungen legen nahe, dass Kühe mehr kognitive Fähigkeiten besitzen, als man bisher angenommen hat. „Wir glauben nicht, dass Veronika eine Einstein unter den Rindern ist“, sagt Auersperg. Sie und ihr Kollege sind vielmehr der Ansicht, dass Kühe unterschätzt werden. „Wir gehen einfach davon aus, dass sie dumm sein müssen, weil sie Nutztiere sind“, so Auersperg. Doch Veronikas Verhalten zeigt das Gegenteil.\n\nDie beiden Forschenden vermuten, dass die Lebensumstände der Kuh dabei entscheidend sind: Veronika wird nicht für die Milch- oder Fleischproduktion gehalten, sondern lebt frei und ist für die Familie ein geliebtes Haustier. Vielleicht würden wir ähnliche Fälle entdecken, wenn wir uns stärker für die Tiere in unserer Umgebung interessieren würden – und wenn mehr Tiere unter besseren Bedingungen leben dürften.",
