      "id": "l-75607606",
      "title": "UN-Entwicklungsprogramm verlegt Jobs nach Europa",
      "date": "2026-01-23",
      "transcript": "UN-Entwicklungsprogramm verlegt Jobs nach Europa\n\nDie USA haben angekündigt, sich aus verschiedenen UN-Organisationen und Entwicklungsprogrammen zurückzuziehen. Nun verlegen die UN Hunderte Stellen von New York nach Deutschland und Spanien.\n\nAuf den ersten Blick ist es nur eine organisatorische Entscheidung: Das Entwicklungsprogramm UNDP (United Nations Development Programme) verlegt rund 300 Stellen von New York nach Bonn und 100 weitere nach Madrid. Doch diese Entscheidung ist auch ein „wichtiges politisches Signal“, so der deutsche Außenminister Johann Wadephul, „gerade in Zeiten, in denen das UN-System und multilaterale Prinzipien unter Druck stehen.“ Weltweite Herausforderungen wie Kriege, Hunger und Umweltzerstörung können nur in Zusammenarbeit gelöst werden, heißt es in der Erklärung weiter.\n\nDas sieht US-Präsident Donald Trump bekanntlich ganz anders. Er macht aus seiner Verachtung für die UN kein Geheimnis. Deshalb sieht Martin Kaiser von Greenpeace die Verlegung positiv: „UN-Institutionen müssen ungehindert und ohne Angst vor politischen Repressalien weiterarbeiten können“, meint er. Die US-Regierung unter Trump „arbeitet momentan mit politischer und wirtschaftlicher Erpressung und verfolgt imperiale Landnahme-Absichten“, so Kaiser.\n\nDas UNDP hat etwa 22.000 Mitarbeitende in 170 Ländern. Es arbeitet in den Bereichen Armutsbekämpfung, Zugang zu Energie und sauberem Wasser, Bildung und Klimaschutz. Und, in diesen Zeiten besonders wichtig: Es geht dabei auch um die Förderung von Demokratie und um internationale Zusammenarbeit. Deutschland ist einer der größten Geldgeber, während Donald Trump angekündigt hat, sich aus vielen wichtigen UN-Organisationen zurückzuziehen.\n\nDoch warum Bonn? Der Standort gehört zu den wichtigsten Zentren der UN. Nach dem Zweiten Weltkrieg war die Stadt am Rhein zunächst Regierungssitz und Hauptstadt Westdeutschlands. Nach der Wiedervereinigung wurde dann zwar Berlin die neue gesamtdeutsche Hauptstadt. Trotzdem gibt es auch aktuell immer noch viele Bundesbehörden in Bonn – und auch die zahlreichen UN-Organisationen sind geblieben. Heute sind die UN mit 27 Institutionen und etwa 1200 Mitarbeitenden in Bonn vertreten. Dazu kommen nun noch einmal 300 neue Stellen.",
