      "id": "l-75576249",
      "title": "Steigende Lebensmittelpreise, sterbende Bauernhöfe",
      "date": "2026-01-20",
      "transcript": "Steigende Lebensmittelpreise, sterbende Bauernhöfe\n\nLebensmittel werden immer teurer, gleichzeitig müssen landwirtschaftliche Betriebe schließen, weil sie nicht genug verdienen. Wie kann das sein? Ein Grund dafür ist der Einfluss großer Einzelhandelsunternehmen.\n\n \n\nOb Milch, Fleisch oder Gemüse: Kundinnen und Kunden klagen über immer teurere Lebensmittel in den Supermärkten. Um etwa 35 Prozent sind die Preise seit 2020 gestiegen. Doch das Geld kommt nicht bei den Bäuerinnen und Bauern an, sondern vor allem bei den vier großen Unternehmen, die den Lebensmittelhandel in Deutschland kontrollieren. Sie können die Preise festlegen.\n\nGroße Bauernhöfe haben dabei weniger Probleme, ihre Zahl ist in den letzten 15 Jahren sogar gestiegen. Doch kleine und mittlere Höfe müssen schließen, weil sie dem Preisdruck nicht standhalten können. Bisher war die deutsche Landwirtschaft zumindest durch Import-Zölle geschützt. Doch mit dem Freihandelsabkommen Mercosur fallen diese Zölle für Produkte aus Brasilien, Argentinien, Paraguay und Uruguay weg – aus Ländern, die vor allem am Absatz von landwirtschaftlichen Produkten in Europa interessiert sind. Das macht den deutschen Landwirten zusätzliche Sorgen. Können sie mit den Preisen mithalten?\n\nIn einer Studie der Heinrich-Böll-Stiftung heißt es außerdem, dass die Corona-Pandemie, der russische Angriffskrieg auf die Ukraine und die damit verbundenen Schwankungen bei den Öl- und Gaspreisen die Lebensmittelpreise beeinflusst haben.\n\nUm etwas gegen die hohen Preise zu tun, schlägt die SPD nun vor, die wichtigsten Grundnahrungsmittel billiger anzubieten. Andreas Stepphuhn von der „Tafel Deutschland“ hält davon wenig: „Wenn man die soziale Situation hierzulande ändern will, muss man die Einkommenssituation der Menschen ändern.“ Die Politik muss sich stärker mit der wachsenden Armut beschäftigen, meint er. Die Tafeln verteilen gespendete Lebensmittel an Menschen in Armut. Nach eigenen Angaben sind das mittlerweile etwa 1,5 Millionen Menschen.",
