      "id": "l-75489895",
      "title": "Stromausfall – und dann?",
      "date": "2026-01-13",
      "transcript": "Stromausfall – und dann?\n\nDie Menschen in Deutschland sind eigentlich gut versorgt: mit Strom, mit Wasser und mit Lebensmitteln. Doch was passiert, wenn die sogenannte kritische Infrastruktur einmal ausfällt?\n\nBei Zehntausenden Menschen im Südwesten Berlins ging Anfang 2026 das Licht aus. Ein Anschlag auf die Stromversorgung führte zu tagelangen Ausfällen. In vielen Häusern und Wohnungen gab es auch kein warmes Wasser mehr und die Heizungen funktionierten nicht – und das im Winter. Als alles repariert war, fragten sich viele: Wie gut sind wir eigentlich geschützt?\n\nIn Deutschland kümmert sich der Staat um die sogenannte kritische Infrastruktur. Dazu gehören zum Beispiel Strom und Wasser, Internet und Telefon, aber auch Krankenhäuser und Verkehr. Ausfälle sind selten, sagen die zuständigen Behörden. Trotzdem gibt es eine allgemeine Gefahr: „von Sabotageakten oder Cyberangriffen bis hin zu kriegerischen Handlungen“, so das Bundesamt für Bevölkerungsschutz und Katastrophenhilfe (BBK). „Aber auch Extremwetterereignisse oder technisches und menschliches Versagen können zu Ausfällen führen.“\n\nManuel Atug ist Gründer und Sprecher von AG KRITIS, einer unabhängigen Gruppe von Fachleuten, die die kritische Infrastruktur in Deutschland schützen und verbessern möchte. Er findet: Bei all diesen Gefahren müsste der Staat mehr tun, um Krisen zu verhindern. Er kritisiert zum Beispiel, dass Mobilfunkmasten keine eigene Stromversorgung mehr haben – anders als früher. Das bedeutet: Wenn der Strom ausfällt, fallen auch die Telefone aus. Und: „In einer Krise oder Katastrophe“, so Atug, ist „das Wichtigste erst mal nicht Strom, sondern Kommunikation“.\n\nDie Behörden raten den Menschen, für den Notfall vorzusorgen. Man soll einen Vorrat an Lebensmitteln und Wasser anlegen – im besten Fall auch für seine Nachbarn, findet Atug. „Nicht in gigantischen Mengen“, sagt er. Aber eben so viel, dass man mindestens drei Tage übersteht. Nur sorgt heutzutage kaum noch jemand vor, weil in einem Land wie Deutschland ständig alles verfügbar ist. Normalerweise.",
