      "id": "l-75403792",
      "title": "Deutschlands Probleme mit der Digitalisierung",
      "date": "2026-01-06",
      "transcript": "Deutschlands Probleme mit der Digitalisierung \n\nIn Deutschland gehören Faxgeräte und Papierformulare immer noch zum Behördenalltag. Während andere Länder immer digitaler werden, hinkt Deutschlands Verwaltung hinterher. Woran liegt das?\n\nWer in Deutschland umzieht oder ein Auto anmelden möchte, muss das den Behörden mitteilen. Dazu muss man in der Regel wochenlang auf einen Termin vor Ort warten und dann die ausgefüllten Formulare mitbringen. Das ist Alltag auf deutschen Ämtern, denn digitale Angebote gibt es nur selten. „Rund drei Viertel, genauer 77 Prozent der deutschen Unternehmen, nutzen noch Faxgeräte“, erklärt Felix Lesner vom IT-Branchenverband Bitkom. Nur so können sie sicher mit den Behörden kommunizieren. Und das im Jahr 2025.\n\nIm Vergleich zu den anderen 26 EU-Ländern liegt Deutschland bei der digitalen Entwicklung nur im Mittelfeld. Bei der digitalen öffentlichen Verwaltung liegt es sogar weit hinten, auf Platz 24. Dabei fehlt es nicht an Wissen oder Ideen: „Unser Problem ist die Umsetzung“, sagt Frank Reinartz, Leiter der Digitalagentur Düsseldorf. Selbst Städte, die als modern gelten, bieten bisher nur einen Bruchteil ihrer Verwaltungsdienstleistungen online an. In Düsseldorf, einer Stadt mit 650.000 Einwohnerinnen und Einwohnern, sind es nur etwas mehr als 20 Prozent.\n\nEin Grund dafür ist die föderale Struktur Deutschlands. „Es gibt nicht viele Softwarelösungen und Prozesse von der Bundesebene“, so Reinartz. Zuständig sind meist die Bundesländer oder die Kommunenund es fehlen bundesweite Standards. Die Folge: Insellösungen und fehlende Schnittstellen, weil Systeme nicht miteinander arbeiten können.\n\nAndere Länder zeigen längst, wie gut Digitalisierung funktionieren kann. In Dänemark zum Beispiel können mit dem digitalen Personalausweis (eID) über eine zentrale Plattform mehr als 2000 öffentliche Dienstleistungen genutzt werden. Auch Indien hat in nur 15 Jahren ein eigenes zentrales System entwickelt. Es wird nicht nur für die digitale, staatliche Verwaltung genutzt; mittlerweile kann man sogar bei Straßenhändlern mit dem Smartphone zahlen. Nur in Deutschland wird noch diskutiert, wie man am besten digital wird – irgendwann.",
