      "transcript": "Ein kleines Stück Rembrandt\n\nEin Kunstsammler will virtuelle Anteile an einigen seiner Bilder verkaufen. Dadurch könnten auch Menschen, die keine Millionen auf dem Konto haben, ein kleines Stück von einem Rembrandt besitzen.\n\nEinen echten Rembrandt zu kaufen, ist für die meisten Menschen ein Ding der Unmöglichkeit. Die berühmten Gemälde des niederländischen Malers sind oft Millionen wert – wenn sie überhaupt zum Verkauf angeboten werden. Bald soll es aber eine Möglichkeit geben, mit der man zumindest einen kleinen Teil von einem Rembrandt erwerben kann. Der US-amerikanische Kunstsammler Thomas Kaplan hat angekündigt, dass er virtuelle Anteile an einigen Gemälden seiner „Leiden Collection“ verkaufen will.\n\nKaplan begründet sein Vorhaben so: „Ich denke, man kann am besten für Rembrandt begeistern, wenn man Millionen, vielleicht sogar zig Millionen ganz normalen Menschen die Möglichkeit gibt, einen Rembrandt zu besitzen.“ Doch was besitzt man dann genau? Beim Verkauf virtueller Anteile an einem Kunstwerk wird das Eigentum aufgeteilt. Alle besitzen das Kunstwerk also gemeinsam – und nicht eine einzelne Person einen ganz bestimmten Teil.\n\nWer Kunst kauft, macht das in der Regel aus einem von zwei Gründen: Entweder man hat ein künstlerisches Interesse an den Werken. Oder man betrachtet sie als eine Investition, nicht anders als ein Haus oder ein Aktienpaket. Im Fall der „Leiden Collection“ dürfte das Investitionsinteresse entscheidend sein – denn man kann sich das Bild nach dem Kauf ja nicht in die eigene Wohnung hängen.\n\nManche meinen, dass mit Kaplans Idee jetzt eine „Demokratisierung des Kunstmarkts“ kommt. Experte Dirk Boll glaubt jedoch nicht daran: „Das ist ein schöner Slogan“, sagt er. Für Boll kann man den Kunstmarkt eher mit einem Autohaus vergleichen: „Sie können sich jedes Auto kaufen, das Sie sich leisten können. Und je nachdem, wie viel Geld Sie haben, ist es entweder ein VW Polo oder eine Mercedes S-Klasse.“ Für die Leiden Collection gilt jedoch: Auch wenn jemand so viel Geld hätte, alle virtuellen Anteile zu kaufen, bleiben die Bilder in Kaplans Besitz. Denn er hat angekündigt, dass er die Mehrheit der Anteile behalten will.",
